{
  "checks": [
    {
      "problem": "每条问题与其修复动作分散在不同节里，编号体系也对不上，清单本身只有严重度标签和一句话描述，读者无法把某条问题直接对到它的修改动作，还可能漏掉最严重的那条",
      "A": "部分解决",
      "B": "解决"
    }
  ],
  "worse": [
    {
      "version": "A",
      "where": "明细·问题清单 与 下一步·修改建议（P1/P2/P3 卡片）",
      "why": "A 的问题清单只有 编号/问题/类型/严重度/影响，既没有“位置”也没有“建议”，读者想知道某条怎么改必须往下翻到“下一步”；而“下一步”三张卡片的标题只写位置——“P1·配送进度条”和“P3·配送进度条”完全同名，回到清单还得靠 P 编号重新辨认哪张卡对应哪条。B 把位置和建议并进清单同一行，卡片标题又直接用问题原句（“P1 进度条用红绿区分准时与超时”），一次就能对上，不必来回翻。"
    }
  ],
  "better": "B",
  "reason": "B 的问题清单一行里同时给出位置、影响、严重度和建议，下一步的卡片标题与清单用同一套问题原句，读者从“哪条问题”到“怎么改”一次看完；A 要在明细和下一步两节之间来回翻，还要靠 P 编号在两处重认。",
  "next": [
    {
      "where": "明细·问题清单",
      "task": "判断 P1 与 P3 是不是同一件事、该按哪条去改",
      "why": "P1 和 P3 的位置都写“配送进度条”，影响都是“红色盲、绿色盲”，只是一个写“混淆色”、一个写“仅靠颜色”，清单里没有说明两条的关系或先后，读者要自己比对两行才敢动手。"
    },
    {
      "where": "下一步·建议改动",
      "task": "核对 P1、P3 改完后的效果",
      "why": "这张表只有“顶部白色标题”一行的前后色值（P2），P1 加“已超时 X 分钟”文字、P3 加时钟图标的改动没有对应的前后对照或落点说明，读者想确认这两条改到什么程度只能回到清单里那一句建议。"
    },
    {
      "where": "色觉模拟（四张色盲截图）与 明细·问题清单",
      "task": "从某张模拟图里看到的看不清的地方，找到对应的那条问题",
      "why": "截图下方只标了“原界面/红色盲/绿色盲/蓝色盲”，没有标出图中哪处对应 P1 或 P3，读者要先去“色差对照”表再翻到“问题清单”，中间多一次跨节对照。"
    }
  ]
}
